-- Instalación en una base NUEVA y VACÍA. No usar como migración del dump de 2022.
-- Crear y seleccionar la base manualmente antes de ejecutar.
CREATE TABLE IF NOT EXISTS catalogo_parametros (id_catalogo INT PRIMARY KEY, nombre_catalogo VARCHAR(255) NOT NULL, estado INT DEFAULT 1);
CREATE TABLE IF NOT EXISTS parametros (id_parametro INT PRIMARY KEY, id_catalogo INT NOT NULL, nombre_parametro VARCHAR(255) NOT NULL, orden INT NOT NULL, estado INT DEFAULT 1, FOREIGN KEY(id_catalogo) REFERENCES catalogo_parametros(id_catalogo));
CREATE TABLE IF NOT EXISTS personas (id_persona INT AUTO_INCREMENT PRIMARY KEY, id_tipo_documento INT NOT NULL, numero_documento VARCHAR(20) NOT NULL, nombres VARCHAR(255) NOT NULL, ape_paterno VARCHAR(255) NOT NULL, ape_materno VARCHAR(255) NOT NULL, fecha_nacimiento DATE NOT NULL, email VARCHAR(100), celular VARCHAR(15), UNIQUE(numero_documento), FOREIGN KEY(id_tipo_documento) REFERENCES parametros(id_parametro));
CREATE TABLE IF NOT EXISTS usuarios (id_usuario INT AUTO_INCREMENT PRIMARY KEY, id_persona INT NOT NULL UNIQUE, clave VARCHAR(255) NOT NULL, estado INT NOT NULL DEFAULT 1, FOREIGN KEY(id_persona) REFERENCES personas(id_persona));
CREATE TABLE IF NOT EXISTS roles (id_rol INT PRIMARY KEY, nombre_rol VARCHAR(255) NOT NULL, estado INT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS usuario_rol (id_usuario INT NOT NULL, id_rol INT NOT NULL, estado INT NOT NULL DEFAULT 1, PRIMARY KEY(id_usuario,id_rol), FOREIGN KEY(id_usuario) REFERENCES usuarios(id_usuario), FOREIGN KEY(id_rol) REFERENCES roles(id_rol));
CREATE TABLE IF NOT EXISTS especialidades_doctor (id_usuario INT NOT NULL, id_especialidad INT NOT NULL, estado INT DEFAULT 1, PRIMARY KEY(id_usuario,id_especialidad), FOREIGN KEY(id_usuario) REFERENCES usuarios(id_usuario), FOREIGN KEY(id_especialidad) REFERENCES parametros(id_parametro));
CREATE TABLE IF NOT EXISTS citas (id_cita INT AUTO_INCREMENT PRIMARY KEY, id_paciente INT NOT NULL, id_doctor INT NOT NULL, fecha_hora TIMESTAMP NOT NULL, motivo VARCHAR(500) NOT NULL, estado VARCHAR(20) NOT NULL DEFAULT 'PROGRAMADA', doctor_activo INT, paciente_activo INT, UNIQUE(doctor_activo,fecha_hora), UNIQUE(paciente_activo,fecha_hora), CHECK(estado IN ('PROGRAMADA','CANCELADA')), CHECK((estado='PROGRAMADA' AND doctor_activo IS NOT NULL AND paciente_activo IS NOT NULL AND doctor_activo=id_doctor AND paciente_activo=id_paciente) OR (estado='CANCELADA' AND doctor_activo IS NULL AND paciente_activo IS NULL)), FOREIGN KEY(id_paciente) REFERENCES usuarios(id_usuario), FOREIGN KEY(id_doctor) REFERENCES usuarios(id_usuario));
CREATE TABLE IF NOT EXISTS reclamos (id_reclamo INT AUTO_INCREMENT PRIMARY KEY, id_usuario INT NOT NULL, detalle VARCHAR(2000) NOT NULL, fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(id_usuario) REFERENCES usuarios(id_usuario));

